// auth.config.ts
import { AuthConfig } from 'angular-oauth2-oidc';

export const authConfig: AuthConfig = {
  // URL of the Identity Provider
  issuer: 'https://accounts.google.com',

  // URL of the SPA to redirect the user to after login
  redirectUri: window.location.origin,

  // The SPA's id. The SPA is registered with this id at the auth-server
  clientId: '780004476307-l9r1453e7ta72etv7mnl866of73vccj6.apps.googleusercontent.com',

  // set the scope for the permissions the client should request
  scope: 'openid profile email',

  // Use 'code' for Authorization Code Flow with PKCE
  responseType: 'code',

  // Disable strict discovery document validation
  strictDiscoveryDocumentValidation: false,

  // Required for Google OAuth
  oidc: true,

  // Use HTTPS for production
  requireHttps: window.location.protocol === 'https:',

  // Show debug information
  showDebugInformation: true,

  // Additional parameters for Google OAuth
  customQueryParams: {
    prompt: 'consent',
    access_type: 'offline'
  }
};
